for C in (0.01, 0.1, 1000):
    m = SVC(kernel="linear", C=C).fit(X, y)
    print(C, m.n_support_.sum(), round(2 / np.linalg.norm(m.coef_), 3))

for gamma in (0.01, 1, 100):
    m = SVC(gamma=gamma).fit(X, y)
    print(gamma, round(m.score(X, y), 3), cross_val_score(SVC(gamma=gamma), X, y, cv=5).mean().round(3), m.n_support_.sum())

for eps in (0.05, 0.3, 1.0):
    labels = DBSCAN(eps=eps, min_samples=5).fit_predict(X)
    print(eps, len(set(labels.tolist()) - {-1}), int((labels == -1).sum()))
